let products = loadProducts();
let selectedPhotos = [];

const $ = (id) => document.getElementById(id);
const catalog = $('catalog');
const stats = $('stats');
const emptyState = $('emptyState');
const adminDialog = $('adminDialog');
const detailDialog = $('detailDialog');

function deepCopyBase(){ return JSON.parse(JSON.stringify(excelProducts)); }
function uid(){ return (crypto && crypto.randomUUID) ? crypto.randomUUID() : 'local-' + Date.now() + '-' + Math.random().toString(16).slice(2); }

function loadProducts(){
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if(!raw) return deepCopyBase();
    const saved = JSON.parse(raw);
    if(saved && saved.dataVersion === DATA_VERSION && Array.isArray(saved.products)) return saved.products;
  } catch(e) {}
  return deepCopyBase();
}
function saveProducts(){
  localStorage.setItem(STORAGE_KEY, JSON.stringify({dataVersion:DATA_VERSION, products}));
}
function money(value){
  const n = Number(value || 0);
  return n > 0 ? new Intl.NumberFormat('uk-UA', {maximumFractionDigits:2}).format(n) + ' грн' : '—';
}
function statusClass(status){
  const s=(status||'').toLowerCase();
  if(s.includes('продан')) return 'sold';
  if(s.includes('брон')) return 'reserved';
  if(s.includes('поки що не')) return 'hold';
  if(s.includes('не подано')) return 'pending';
  return 'sale';
}
function escapeHtml(str=''){
  return String(str).replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[ch]));
}
function escapeJs(str=''){ return String(str).replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }
function imagePath(name){ return 'images/' + encodeURIComponent(name).replace(/%2F/g,'/'); }
function drivePhotoSrc(photo){ return photo?.thumbUrl || photo?.driveUrl || ''; }
function normalizeUrl(v){
  if(!v) return '';
  const s=String(v).trim().replace(/\\\./g,'.');
  return /^https?:\/\//i.test(s) ? s : '';
}
function displayValue(v){
  if(v === null || v === undefined || v === '') return '—';
  return String(v);
}
function renderValue(label, value){
  const text=displayValue(value);
  const url=normalizeUrl(value);
  if(url) return `<a href="${escapeHtml(url)}" target="_blank" rel="noopener">${escapeHtml(text)}</a>`;
  return escapeHtml(text);
}
function renderExcelSection(title, obj){
  if(!obj) return '';
  return `<details class="excel-section" open>
    <summary>${escapeHtml(title)}</summary>
    <table class="excel-table"><tbody>${Object.entries(obj).map(([k,v])=>`<tr><th>${escapeHtml(k)}</th><td>${renderValue(k,v)}</td></tr>`).join('')}</tbody></table>
  </details>`;
}

function renderFilters(){
  const cat = $('categoryFilter');
  const st = $('statusFilter');
  const currentCat = cat.value;
  const currentSt = st.value;
  const categories = [...new Set(products.map(p=>p.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'uk'));
  const statuses = [...new Set(products.map(p=>p.status).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'uk'));
  cat.innerHTML = '<option value="all">Усі категорії</option>' + categories.map(c=>`<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
  st.innerHTML = '<option value="all">Усі статуси</option>' + statuses.map(s=>`<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');
  cat.value = categories.includes(currentCat) ? currentCat : 'all';
  st.value = statuses.includes(currentSt) ? currentSt : 'all';
}

function renderStats(){
  const total = products.length;
  const withPhoto = products.filter(p=>(p.drivePhotos||[]).length || (p.photoNames||[]).length || (p.photos||[]).length).length;
  const withOlxPrice = products.filter(p=>Number(p.priceOlxUsed||p.priceSubmitted||p.price||0)>0).length;
  const withNewPrice = products.filter(p=>Number(p.newPrice||0)>0).length;
  stats.innerHTML = [
    ['Усього позицій',total],['З фото',withPhoto],['З ціною OLX',withOlxPrice],['З ціною нового',withNewPrice]
  ].map(([label,val])=>`<div class="stat"><b>${val}</b><span>${label}</span></div>`).join('');
}

function cardImage(p){
  if(p.photos?.[0]) return `<img src="${p.photos[0]}" alt="${escapeHtml(p.name)}">`;
  if(p.drivePhotos?.[0]) {
    const ph=p.drivePhotos[0];
    return `<img src="${escapeHtml(drivePhotoSrc(ph))}" alt="${escapeHtml(p.name)}" referrerpolicy="no-referrer" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="no-photo image-fallback" style="display:none">Фото є в Google Drive<br><a href="${escapeHtml(ph.driveUrl)}" target="_blank" rel="noopener">Відкрити фото</a></div>`;
  }
  if(p.photoNames?.[0]) {
    return `<img src="${imagePath(p.photoNames[0])}" alt="${escapeHtml(p.name)}" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="no-photo image-fallback" style="display:none">Фото в Excel: ${p.photoNames.length}<br>${escapeHtml(p.photoNames[0])}</div>`;
  }
  return '<div class="no-photo">Немає фото</div>';
}

function productSearchText(p){
  return `${p.inventoryNo||''} ${p.name||''} ${p.sourceName||''} ${p.description||''} ${p.location||''} ${p.category||''} ${JSON.stringify(p.excelZvit||{})} ${JSON.stringify(p.excelSource||{})}`.toLowerCase();
}

function renderCatalog(){
  const q = $('searchInput').value.trim().toLowerCase();
  const category = $('categoryFilter').value;
  const status = $('statusFilter').value;
  const filtered = products.filter(p => (!q || productSearchText(p).includes(q)) && (category==='all' || p.category===category) && (status==='all' || p.status===status));

  catalog.innerHTML = filtered.map(p => `
    <article class="card">
      <div class="card-image">
        ${cardImage(p)}
        <span class="badge">${escapeHtml(p.condition || 'Б/У')}</span>
      </div>
      <div class="card-body">
        <span class="status ${statusClass(p.status)}">${escapeHtml(p.status || 'Не визначено')}</span>
        <h3>${escapeHtml(p.name)}</h3>
        ${p.sourceName && p.sourceName!==p.name ? `<div class="source-name">${escapeHtml(p.sourceName)}</div>` : ''}
        <div class="meta"><span>${escapeHtml(p.inventoryNo||'Без інв. №')}</span><span>•</span><span>${escapeHtml(p.category||'')}</span></div>
        <div class="meta"><span>${escapeHtml(p.location || 'Локація не вказана')}</span></div>
        <div class="price">${money(p.price)}</div>
        <div class="card-actions"><button class="btn ghost" onclick="openDetails('${escapeJs(p.id)}')">Детальніше</button></div>
      </div>
    </article>`).join('');

  emptyState.classList.toggle('hidden', filtered.length>0);
  renderStats();
}

$('openAdminBtn').addEventListener('click',()=>adminDialog.showModal());
$('closeAdminBtn').addEventListener('click',()=>adminDialog.close());
$('cancelBtn').addEventListener('click',()=>adminDialog.close());
['searchInput','categoryFilter','statusFilter'].forEach(id => $(id).addEventListener(id==='searchInput'?'input':'change', renderCatalog));

$('photos').addEventListener('change', async (e)=>{
  const files = [...e.target.files].slice(0,3);
  selectedPhotos = [];
  for (const file of files) selectedPhotos.push(await resizeImage(file, 1100, .78));
  $('photoPreview').innerHTML = selectedPhotos.map(src=>`<img src="${src}">`).join('');
});

$('productForm').addEventListener('submit',(e)=>{
  e.preventDefault();
  const product = {
    id: uid(), inventoryNo:'', name:$('name').value.trim(), sourceName:'', category:$('category').value.trim(),
    price:Number($('price').value||0), priceOlxUsed:Number($('price').value||0), priceSubmitted:0, priceProposed:0,
    newPrice:0, residualValue:0, location:$('location').value.trim(), quantity:1, condition:$('condition').value,
    status:$('status').value, description:$('description').value.trim(), photoNames:[], drivePhotos:[], photos:selectedPhotos,
    newEquipmentLink:'', olxUsedLink:'', olxLink:'', excelZvit:null, excelSource:null
  };
  products.unshift(product);
  try { saveProducts(); } catch(err) { alert('Браузер не зміг зберегти дані. Спробуй менші фото або видали частину локально доданих позицій.'); return; }
  e.target.reset(); selectedPhotos=[]; $('photoPreview').innerHTML=''; adminDialog.close(); renderFilters(); renderCatalog();
});

$('resetDemoBtn').addEventListener('click',()=>{
  if(confirm('Відновити всі 252 позиції з Excel та видалити локальні зміни?')){
    products=deepCopyBase();
    try{localStorage.removeItem(STORAGE_KEY);}catch(e){}
    renderFilters(); renderCatalog();
  }
});

window.openDetails = function(id){
  const p=products.find(x=>String(x.id)===String(id)); if(!p) return;
  const localImages=p.photos||[];
  const driveImages=p.drivePhotos||[];
  const fileImages=p.photoNames||[];
  let main='<div class="detail-main-image no-photo">Немає фото</div>';
  let thumbs='';
  let driveAction='';

  if(localImages[0]){
    main=`<img id="mainDetailImage" class="detail-main-image" src="${localImages[0]}">`;
    thumbs=localImages.map(src=>`<img src="${src}" onclick="document.getElementById('mainDetailImage').src=this.src">`).join('');
  } else if(driveImages[0]){
    const first=driveImages[0];
    main=`<img id="mainDetailImage" class="detail-main-image" src="${escapeHtml(drivePhotoSrc(first))}" alt="${escapeHtml(p.name)}" referrerpolicy="no-referrer" onerror="this.style.display='none';document.getElementById('detailPhotoFallback').style.display='flex'"><div id="detailPhotoFallback" class="detail-main-image no-photo image-fallback" style="display:none">Не вдалося показати прев’ю з Google Drive.<br><a id="fallbackDriveLink" href="${escapeHtml(first.driveUrl)}" target="_blank" rel="noopener">Відкрити фото в Google Drive</a></div>`;
    thumbs=driveImages.map((ph,i)=>`<button class="drive-thumb" title="${escapeHtml(ph.name||('Фото '+(i+1)))}" onclick="setDriveImage('${escapeJs(ph.thumbUrl)}','${escapeJs(ph.driveUrl)}')"><img src="${escapeHtml(drivePhotoSrc(ph))}" alt="${escapeHtml(ph.name||'Фото')}" referrerpolicy="no-referrer" onerror="this.parentElement.classList.add('thumb-error')"><span>${i+1}</span></button>`).join('');
    driveAction=`<a id="currentDrivePhotoLink" class="btn ghost" href="${escapeHtml(first.driveUrl)}" target="_blank" rel="noopener">Відкрити фото в Google Drive</a>`;
  } else if(fileImages[0]){
    main=`<img id="mainDetailImage" class="detail-main-image" src="${imagePath(fileImages[0])}" onerror="this.style.display='none';document.getElementById('detailPhotoFallback').style.display='flex'"><div id="detailPhotoFallback" class="detail-main-image no-photo image-fallback" style="display:none">У Excel вказано ${fileImages.length} фото.<br>Файли не знайдено.</div>`;
    thumbs=fileImages.map(name=>`<button class="photo-name btn ghost" onclick="setFileImage('${escapeJs(name)}')">${escapeHtml(name)}</button>`).join('');
  }

  const links=[];
  if(p.olxLink) links.push(`<a class="btn primary" href="${escapeHtml(p.olxLink)}" target="_blank" rel="noopener">OLX</a>`);
  if(p.olxUsedLink) links.push(`<a class="btn ghost" href="${escapeHtml(p.olxUsedLink)}" target="_blank" rel="noopener">Аналог OLX</a>`);
  if(p.newEquipmentLink) links.push(`<a class="btn ghost" href="${escapeHtml(p.newEquipmentLink)}" target="_blank" rel="noopener">Нове обладнання</a>`);
  if(driveAction) links.push(driveAction);

  $('detailContent').innerHTML = `
    <div class="detail-wrap">
      <div class="dialog-head"><div class="eyebrow">КАРТКА ПОЗИЦІЇ</div><button class="icon-btn" onclick="document.getElementById('detailDialog').close()">✕</button></div>
      <div class="detail-grid">
        <div>
          ${main}
          ${driveImages.length ? `<div class="photo-source-note">Фото з Google Drive · ${driveImages.length}</div>` : ''}
          <div class="thumbs">${thumbs}</div>
          ${driveImages.length ? `<div class="photo-file-list">${driveImages.map((x,i)=>`<a class="photo-file photo-file-link" href="${escapeHtml(x.driveUrl)}" target="_blank" rel="noopener">${i+1}. ${escapeHtml(x.name||'Фото')}</a>`).join('')}</div>` : (fileImages.length ? `<div class="photo-file-list">${fileImages.map(x=>`<span class="photo-file">${escapeHtml(x)}</span>`).join('')}</div>` : '')}
        </div>
        <div class="detail-side">
          <span class="status ${statusClass(p.status)}">${escapeHtml(p.status||'Не визначено')}</span>
          <h2>${escapeHtml(p.name)}</h2>
          ${p.sourceName && p.sourceName!==p.name ? `<div class="source-name">Облікова назва: ${escapeHtml(p.sourceName)}</div>` : ''}
          <div class="meta"><span>${escapeHtml(p.inventoryNo||'')}</span><span>•</span><span>${escapeHtml(p.category||'')}</span><span>•</span><span>${escapeHtml(p.condition||'')}</span></div>
          <div class="meta">${escapeHtml(p.location||'')}</div>
          <div class="summary-prices">
            <div class="summary-price"><span>Ціна OLX б/у</span><b>${money(p.priceOlxUsed||p.price)}</b></div>
            <div class="summary-price"><span>Подана ціна OLX</span><b>${money(p.priceSubmitted)}</b></div>
            <div class="summary-price"><span>Ціна нового</span><b>${money(p.newPrice)}</b></div>
            <div class="summary-price"><span>Залишкова вартість</span><b>${money(p.residualValue)}</b></div>
          </div>
          ${links.length ? `<div class="detail-links">${links.join('')}</div>` : ''}
          <div class="detail-desc">${escapeHtml(p.description || 'Опис відсутній')}</div>
          <div class="detail-actions"><button class="btn danger" onclick="deleteProduct('${escapeJs(p.id)}')">Видалити</button></div>
        </div>
      </div>
      ${(p.excelZvit || p.excelSource) ? `<div class="excel-sections"><div class="eyebrow">ВСЯ ІНФОРМАЦІЯ З EXCEL</div>${renderExcelSection('Аркуш «Звіт OLX»',p.excelZvit)}${renderExcelSection('Аркуш «Вихідні дані»',p.excelSource)}</div>` : ''}
    </div>`;
  detailDialog.showModal();
}

window.setDriveImage = function(thumbUrl, driveUrl){
  const img=document.getElementById('mainDetailImage');
  const fb=document.getElementById('detailPhotoFallback');
  const link=document.getElementById('currentDrivePhotoLink');
  const fallbackLink=document.getElementById('fallbackDriveLink');
  if(img){
    img.style.display='block';
    img.src=thumbUrl;
    img.onerror=()=>{ img.style.display='none'; if(fb) fb.style.display='flex'; };
  }
  if(fb) fb.style.display='none';
  if(link) link.href=driveUrl;
  if(fallbackLink) fallbackLink.href=driveUrl;
}

window.setFileImage = function(name){
  const img=document.getElementById('mainDetailImage'); const fb=document.getElementById('detailPhotoFallback'); if(!img) return;
  img.style.display='block'; if(fb) fb.style.display='none'; img.src=imagePath(name);
  img.onerror=()=>{ img.style.display='none'; if(fb){fb.style.display='flex';fb.textContent='Файл '+name+' не знайдено.';} };
}
window.deleteProduct = function(id){
  if(!confirm('Видалити позицію з локальної версії каталогу?')) return;
  products=products.filter(p=>String(p.id)!==String(id));
  try{saveProducts();}catch(e){}
  detailDialog.close(); renderFilters(); renderCatalog();
}
function resizeImage(file, maxSize=1100, quality=.78){
  return new Promise((resolve,reject)=>{
    const img=new Image(); const reader=new FileReader();
    reader.onload=()=>{ img.onload=()=>{
      let {width,height}=img; const scale=Math.min(1,maxSize/Math.max(width,height)); width=Math.round(width*scale);height=Math.round(height*scale);
      const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(img,0,0,width,height);
      resolve(canvas.toDataURL('image/jpeg',quality));
    }; img.onerror=reject; img.src=reader.result; };
    reader.onerror=reject; reader.readAsDataURL(file);
  });
}

renderFilters();
renderCatalog();
